import React from 'react';
import './App.css';
import ZohoAnswerBot from './components/ZobotChat';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <h1>Zoho Answer Bot Integration</h1>
        <p>Test your Zoho Answer Bot locally</p>
      </header>
      <main className="App-main">
        <ZohoAnswerBot 
          botId="YOUR_BOT_ID"
          apiEndpoint="https://desk.zoho.com/api/v1/answerbot"
          apiKey="YOUR_API_KEY"
          orgId="YOUR_ORG_ID"
        />
      </main>
    </div>
  );
}

export default App;
